/** Раздельные источники, проверка фактического графа и измерения оптопары. */
final class PcbOptoTest {
 static final int COMPARATOR=170,LAMP=218,SLIDER=129;
 static double load=1e9;
 static List<PcbCircuitDevice.Part> baseline;
 static void register(CommandDispatcher<CommandSourceStack> d){var r=Commands.literal("pcbopto").requires(s->s.hasPermission(2));
 r.then(Commands.literal("isolated-build").executes(c->isolatedBuild(c.getSource(),false)));
 r.then(Commands.literal("isolated-short").executes(c->isolatedBuild(c.getSource(),true)));
 r.then(Commands.literal("output-power").then(Commands.argument("volts",DoubleArgumentType.doubleArg(0,12)).executes(c->{power(c.getSource(),PcbBridgeTest.BOARD.east(8),DoubleArgumentType.getDouble(c,"volts"));return 1;})));
 r.then(Commands.literal("recipes").executes(c->{for(String id:new String[]{"pcb_optocoupler","pcb_led"})PcbBridgeTest.check(c.getSource().getServer().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("ee_extras:"+id)).isPresent(),"рецепт цепочки загружен "+id);return 1;}));
 r.then(Commands.literal("demo").executes(c->build(c.getSource())));
 r.then(Commands.literal("bias").executes(c->{var source=c.getSource();var l=source.getLevel();var at=PcbBridgeTest.BOARD.west(8);var p=part(source);DevTest.place(l,at,CEEBlocks.CREATIVE_BATTERY.getDefaultState().setValue(CreativeBatteryBlock.AC,false));DevTest.wire(l,at,1,PcbBridgeTest.BOARD,p.b());DevTest.wire(l,at,0,PcbBridgeTest.BOARD,p.coilB());power(source,at,24);return 1;}));
 r.then(Commands.literal("unbias").executes(c->{DevTest.place(c.getSource().getLevel(),PcbBridgeTest.BOARD.west(8),Blocks.AIR.defaultBlockState());return 1;}));
 r.then(Commands.literal("bias-check").executes(c->{var source=c.getSource();var p=part(source);var results=PcbBridgeTest.RESULTS.get(source.getLevel());var at=PcbBridgeTest.BOARD.west(8);double[] a=results.getVoltages(new InWorldNode(0,at)),b=results.getVoltages(new InWorldNode(1,at)),in=results.getVoltages(new InWorldNode(p.b(),PcbBridgeTest.BOARD)),out=results.getVoltages(new InWorldNode(p.coilB(),PcbBridgeTest.BOARD));double leakage=0;for(int i=0;i<a.length;i++){PcbBridgeTest.check(Math.abs(in[i]-out[i]-24)<.01,"реальное смещение земель24В");leakage=Math.max(leakage,Math.abs((24-(b[i]-a[i]))/.001));}PcbBridgeTest.check(a.length>0&&leakage<1e-5,"ток через границу развязки "+leakage);final double measuredLeakage=leakage;source.sendSuccess(()->Component.literal("Смещение земель24В, утечка не более "+measuredLeakage+"А"),false);return report(source);}));
 r.then(Commands.literal("report").executes(c->report(c.getSource())));
 for(boolean light:new boolean[]{false,true})r.then(Commands.literal(light?"light":"dark").executes(c->{PcbBridgeTest.check(measurement(c.getSource()).getBoolean("Light")==light,"световой флаг "+measurement(c.getSource()));return report(c.getSource());}));
 r.then(Commands.literal("expect-output").then(Commands.argument("value",DoubleArgumentType.doubleArg(0,100)).executes(c->{var m=measurement(c.getSource());PcbBridgeTest.check(Math.abs(m.getDouble("Output")-DoubleArgumentType.getDouble(c,"value"))<.03,"контроль выхода "+m);return 1;})));
 r.then(Commands.literal("isolated").executes(c->isolation(c.getSource())));
 r.then(Commands.literal("on").executes(c->control(c.getSource(),true)));
 r.then(Commands.literal("off").executes(c->control(c.getSource(),false)));
 for(boolean on:new boolean[]{false,true})r.then(Commands.literal(on?"high":"low").executes(c->{var m=measurement(c.getSource());PcbBridgeTest.check(on?m.getDouble("Output")>4:m.getDouble("Output")<.02,"уровень выхода "+m);return report(c.getSource());}));
 r.then(Commands.literal("input").then(Commands.argument("volts",DoubleArgumentType.doubleArg(-12,12)).executes(c->{power(c.getSource(),PcbBridgeTest.BOARD.west(5),DoubleArgumentType.getDouble(c,"volts"));return 1;})));
 r.then(Commands.literal("load").then(Commands.argument("ohms",DoubleArgumentType.doubleArg(.01,1e9)).executes(c->{load=DoubleArgumentType.getDouble(c,"ohms");var s=c.getSource();var p=part(s);var list=new ArrayList<>(baseline);list.add(new PcbCircuitDevice.Part(PcbCircuitDevice.Kind.RESISTOR,p.alternate(),p.coilB(),load,0,0,1));PcbModulesTest.call(PcbCircuitDevice.class,PcbBridgeTest.device(s),"setCircuit",list,PcbCircuitDevice.Rating.L2,PcbSensorTest.demo(s)?2:5);control(s,true);return 1;})));
 r.then(Commands.literal("restore").executes(c->{var s=c.getSource();baseline=PcbModulesTest.call(PcbBridgeTest.wiring(),null,"compile",(CompoundTag)PcbModulesTest.call(PcbCircuitBlockEntity.class,s.getLevel().getBlockEntity(PcbBridgeTest.BOARD),"topology"));PcbModulesTest.call(PcbCircuitDevice.class,PcbBridgeTest.device(s),"setCircuit",baseline,PcbCircuitDevice.Rating.L2,PcbSensorTest.demo(s)?2:5);load=1e9;control(s,true);return 1;}));
 r.then(Commands.literal("geometry").executes(c->{for(int rot=0;rot<4;rot++)for(boolean mirror:new boolean[]{false,true}){var t=PcbTopology.create(2);int def=PcbModulesTest.definition(34,rot);if(mirror)def=PcbModulesTest.call(PcbBridgeTest.wiring(),null,"mirror",def);PcbTopology.set(t,0,85,PcbTopology.COMPONENT);PcbModulesTest.call(PcbTopology.class,null,"setPart",t,0,85,def);for(int pin=0;pin<5;pin++)PcbTopology.set(t,0,(int)PcbModulesTest.call(PcbBridgeTest.wiring(),null,"pinCell",85,def,pin),PcbTopology.TRACE);List<PcbCircuitDevice.Part> parts=PcbModulesTest.call(PcbBridgeTest.wiring(),null,"compile",t);PcbBridgeTest.check(parts!=null&&parts.size()==1,"геометрия оптопары");PcbBridgeTest.check(java.util.stream.IntStream.of(parts.get(0).a(),parts.get(0).b(),parts.get(0).coilA(),parts.get(0).coilB(),parts.get(0).alternate()).distinct().count()==5,"независимые выводы");}return 1;}));
 d.register(r); }
 static PcbCircuitDevice.Part part(CommandSourceStack s){return PcbOptoTest.<List<PcbCircuitDevice.Part>>parts(s).stream().filter(p->p.kind()==PcbCircuitDevice.Kind.OPTOCOUPLER).findFirst().orElseThrow();}
 @SuppressWarnings("unchecked") static <T> T parts(CommandSourceStack s){return (T)PcbModulesTest.call(PcbBridgeTest.wiring(),null,"compile",(CompoundTag)PcbModulesTest.call(PcbCircuitBlockEntity.class,s.getLevel().getBlockEntity(PcbBridgeTest.BOARD),"topology"));}
 static CompoundTag measurement(CommandSourceStack s){var all=PcbBridgeTest.snapshot(s).getCompound("Optocouplers");PcbBridgeTest.check(all.size()==1,"единственная оптопара");return all.getCompound(all.getAllKeys().iterator().next());}
 static int report(CommandSourceStack s){var m=measurement(s);PcbBridgeTest.check(!PcbBridgeTest.snapshot(s).getBoolean("Burnt"),"плата цела");PcbBridgeTest.check(Math.abs(m.getDouble("InputWatts")+m.getDouble("SupplyWatts")-m.getDouble("OutputWatts")-m.getDouble("Watts"))<1e-5,"энергобаланс "+m);double expected=m.getDouble("Supply")*(m.getBoolean("Driving")?10000.0/10100:10000.0/1000010000)/(1+m.getDouble("OutputResistance")/load);PcbBridgeTest.check(Math.abs(expected-m.getDouble("Output"))<.025,"независимая нагрузочная характеристика "+expected+" / "+m);s.sendSuccess(()->Component.literal("Оптопара: "+m+", индикатор="+s.getLevel().getBlockState(PcbBridgeTest.BOARD).getValue(PcbCircuitBlock.LIT)),false);return 1;}
 static void power(CommandSourceStack s,BlockPos battery,double volts){var saved=PcbBridgeTest.BATTERY;PcbBridgeTest.BATTERY=battery;PcbBridgeTest.power(s,volts,false);PcbBridgeTest.BATTERY=saved;}
 static int control(CommandSourceStack s,boolean on){if(!PcbSensorTest.demo(s))return 1;var list=PcbBridgeTest.snapshot(s).getList("Circuit",Tag.TAG_COMPOUND);int ordinal=0;var switches=PcbBridgeTest.snapshot(s).getLong("Switches");for(int i=0;i<list.size();i++){var p=list.getCompound(i);if(p.getInt("ModuleIndex")==109){boolean actual=(switches&(1L<<i))!=0;if(actual!=on)PcbModulesTest.call(PcbCircuitDevice.class,PcbBridgeTest.device(s),"interactComponent",ordinal,s.getLevel().getGameTime(),false);return 1;}if(!p.getString("Kind").equals("TRACE"))ordinal++;}throw new IllegalStateException("Нет переключателя");}
 static Object field(Object o,String n){try{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new IllegalStateException(e);}}
 static int isolation(CommandSourceStack s){var builder=PcbBridgeTest.RESULTS.get(s.getLevel()).circuitBuilder;var p=part(s);var start=builder.getNode(new InWorldNode(p.b(),PcbBridgeTest.BOARD));var target=builder.getNode(new InWorldNode(p.coilB(),PcbBridgeTest.BOARD));var todo=new ArrayDeque<Object>();var seen=new HashSet<Object>();todo.add(start);while(!todo.isEmpty()){var node=todo.remove();if(!seen.add(node))continue;PcbBridgeTest.check(node!=target,"обнаружен путь между землями");var adj=(it.unimi.dsi.fastutil.ints.Int2ObjectMap<?>)field(node,"adjacency");for(int id:adj.keySet())todo.add(builder.getNode(id));}PcbBridgeTest.check(seen.size()>2&&seen.contains(builder.getNode(new InWorldNode(p.a(),PcbBridgeTest.BOARD))),"обход включил обе клеммы входа");s.sendSuccess(()->Component.literal("Развязка: между землями нет пути в фактическом графе EE; проверено узлов "+seen.size()),false);return 1;}
    static CompoundTag topology(){var t=PcbTopology.create(2);int[] nets=new int[512];Arrays.fill(nets,-1);boolean[] blocked=new boolean[512];var endpoints=new ArrayList<List<Integer>>();for(int i=0;i<17;i++)endpoints.add(new ArrayList<>());
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,17,27,new int[]{0,1},0,9);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,23,29,new int[]{0,1,2,3},0,0);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,84,7,new int[]{2,3},100,0);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,89,30,new int[]{2,3,9,3},0,0);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,149,34,new int[]{15,14,9,3,10},0,0);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,COMPARATOR,22,new int[]{10,11,12,9,3},0,0);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,SLIDER,15,new int[]{9,3,11},10000,0);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,LAMP,4,new int[]{12,3},1000,2);
        PcbRegulatorDemo.add(t,nets,blocked,endpoints,109,3,new int[]{15,13,16},0,0);
        for(int[] pair:new int[][]{{159,13},{224,14}}){int cell=pair[0],net=pair[1];nets[cell]=nets[cell+256]=net;endpoints.get(net).add(cell);}
        for(int net:new int[]{12,1,13,9,5,3,6,8,11,4,15,0,16,10,14,2,7}){var points=endpoints.get(net);for(int i=1;i<points.size();i++)PcbRegulatorDemo.route(nets,blocked,points.get(0)+256,points.get(i)+256,net);}
        for(int i=0;i<512;i++)if(nets[i]>=0){int cell=i%256;PcbTopology.set(t,i/256,cell,nets[cell]>=0&&nets[cell]==nets[cell+256]?PcbTopology.VIA:PcbTopology.TRACE);}
        for(int layer=0;layer<2;layer++)for(int cell=0;cell<256;cell++)for(int direction:new int[]{1,3}){int next=direction==1?(cell%16==15?-1:cell+1):(cell>=240?-1:cell+16);if(next>=0&&nets[layer*256+cell]>=0&&nets[layer*256+next]>=0&&nets[layer*256+cell]!=nets[layer*256+next])PcbModulesTest.call(PcbTopology.class,null,"setEdgeCut",t,layer,cell,direction,true);}
        PcbTopology.set(t,0,159,PcbTopology.TERMINAL);PcbTopology.set(t,0,224,PcbTopology.TERMINAL);
        String error=PcbTopology.validate(t);PcbBridgeTest.check(error==null,"проект датчика "+error);return t;
    }
 static int isolatedBuild(CommandSourceStack s,boolean shorted){var l=s.getLevel();var board=PcbBridgeTest.BOARD;PcbBridgeTest.BATTERY=board.east(8);load=shorted?.01:1e9;for(var pos:new BlockPos[]{board,PcbBridgeTest.BATTERY,board.west(5)})DevTest.place(l,pos,Blocks.AIR.defaultBlockState());
 var t=PcbTopology.create(2);int def=PcbModulesTest.definition(34,0);PcbTopology.set(t,0,85,PcbTopology.COMPONENT);PcbModulesTest.call(PcbTopology.class,null,"setPart",t,0,85,def);
 for(int pin=0;pin<5;pin++){int cell=PcbModulesTest.call(PcbBridgeTest.wiring(),null,"pinCell",85,def,pin);int dx=pin<2?-1:1;while(cell%16!=0&&cell%16!=15){PcbTopology.set(t,0,cell,PcbTopology.TRACE);cell+=dx;}PcbTopology.set(t,0,cell,PcbTopology.TERMINAL);}
 for(int row=5;row<=6;row++)for(int x=8;x<16;x++)if(!shorted||row!=6||x!=15)PcbModulesTest.call(PcbTopology.class,null,"setEdgeCut",t,0,row*16+x,3,true);
 DevTest.place(l,board,PcbItems.CIRCUIT_BLOCK.get().defaultBlockState().setValue(PcbCircuitBlock.CUSTOM,true));var stack=PcbItems.L2_BOARD.toStack();PcbTopology.attach(stack,t);PcbModulesTest.call(PcbCircuitBlockEntity.class,l.getBlockEntity(board),"setBoard",stack);baseline=PcbModulesTest.call(PcbBridgeTest.wiring(),null,"compile",t);PcbBridgeTest.check(baseline!=null&&baseline.stream().filter(p->p.kind()!=PcbCircuitDevice.Kind.TRACE).count()==1,"изолированный проект");PcbModulesTest.call(PcbCircuitDevice.class,PcbBridgeTest.device(s),"setCircuit",baseline,PcbCircuitDevice.Rating.L2,5);var p=baseline.stream().filter(q->q.kind()==PcbCircuitDevice.Kind.OPTOCOUPLER).findFirst().orElseThrow();
 var input=board.west(5);DevTest.place(l,input,CEEBlocks.CREATIVE_BATTERY.getDefaultState().setValue(CreativeBatteryBlock.AC,false));DevTest.place(l,PcbBridgeTest.BATTERY,CEEBlocks.CREATIVE_BATTERY.getDefaultState().setValue(CreativeBatteryBlock.AC,false));DevTest.wire(l,input,1,board,p.a());DevTest.wire(l,input,0,board,p.b());DevTest.wire(l,PcbBridgeTest.BATTERY,1,board,p.coilA());DevTest.wire(l,PcbBridgeTest.BATTERY,0,board,p.coilB());power(s,input,5);power(s,PcbBridgeTest.BATTERY,5);return 1; }
 static int build(CommandSourceStack s){var l=s.getLevel();var board=PcbBridgeTest.BOARD;PcbBridgeTest.BATTERY=board.east(8);load=1e9;
 for(var p:new BlockPos[]{board,PcbBridgeTest.BATTERY,board.west(5),board.east(5)})DevTest.place(l,p,Blocks.AIR.defaultBlockState());
 var t=topology();DevTest.place(l,board,PcbItems.CIRCUIT_BLOCK.get().defaultBlockState().setValue(PcbCircuitBlock.CUSTOM,true));var stack=PcbItems.L2_BOARD.toStack();PcbTopology.attach(stack,t);PcbModulesTest.call(PcbCircuitBlockEntity.class,l.getBlockEntity(board),"setBoard",stack);baseline=PcbModulesTest.call(PcbBridgeTest.wiring(),null,"compile",t);PcbBridgeTest.check(baseline!=null&&baseline.stream().filter(p->p.kind()!=PcbCircuitDevice.Kind.TRACE).count()==9,"девять реальных модулей");PcbModulesTest.call(PcbCircuitDevice.class,PcbBridgeTest.device(s),"setCircuit",baseline,PcbCircuitDevice.Rating.L2,2);
 DevTest.place(l,PcbBridgeTest.BATTERY,CEEBlocks.CREATIVE_BATTERY.getDefaultState().setValue(CreativeBatteryBlock.AC,true));var input=board.east(5);DevTest.place(l,input,Extras.eeTermination());var end=Extras.end(l,input);DevTest.wire(l,PcbBridgeTest.BATTERY,0,input,end.conductor(1).id());DevTest.wire(l,PcbBridgeTest.BATTERY,1,input,end.conductor(2).id());PcbBridgeTest.check(CableLaying.connect(l,CableKind.DUPLEX,end,CableEnd.of(l,board,l.getBlockState(board))),"ввод трансформатора");PcbBridgeTest.power(s,300,true);
 var battery=board.west(5);DevTest.place(l,battery,CEEBlocks.CREATIVE_BATTERY.getDefaultState().setValue(CreativeBatteryBlock.AC,false));DevTest.wire(l,battery,1,board,0);DevTest.wire(l,battery,0,board,1);power(s,battery,5);control(s,true);
 PcbBridgeTest.check(s.getServer().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("ee_extras:pcb_optocoupler")).isPresent(),"рецепт загружен");return 1; }
}
